// The types of DNS record that a user can make.
var dnsRecordTypes = []string{"A", "AAAA", "CNAME", "MX", "TXT", "SRV", "CAA", "NS"}

// Names that the database servers use (CF-01).
var reservedDatabaseNames = []string{"mysql", "sys", "information_schema", "performance_schema", "postgres", "template0", "template1", "root", "mariadb.sys", "healthcheck"}

// A database name does not start with one of these (CF-01).
var reservedDatabasePrefixes = []string{"pg_"}

// The names of the built-in runtimes, the image families and the database engines. A pack cannot have one of these names.
var reservedRuntimeNames = []string{"frankenphp", "apache-php-fpm", "node", "python", "custom", "static", "edge", "mail", "dns", "database", "mariadb", "postgresql", "valkey"}

// MaxBuildCommands: The largest number of build commands of a deploy.
const MaxBuildCommands = 10

// MaxCertificateBytes: The largest size of a certificate chain or of a private key in PEM format, in bytes.
const MaxCertificateBytes = 65536

// MaxCertificateHosts: The largest number of hosts that use one certificate on one server.
const MaxCertificateHosts = 5000

// MaxCertificatesPerServer: The largest number of certificates from the panel on one server.
const MaxCertificatesPerServer = 2000

// MaxCommandArguments: The largest number of arguments of a start command.
const MaxCommandArguments = 32

// MaxContainerEnvironment: The largest number of environment variables of a container.
const MaxContainerEnvironment = 20

// MaxCronJobs: The largest number of cron jobs of a website.
const MaxCronJobs = 20

// MaxDeploySecrets: The largest number of secrets of a deploy.
const MaxDeploySecrets = 50

// MaxDnsRecordsPerZone: The largest number of records in a DNS zone.
const MaxDnsRecordsPerZone = 1000

// MinDnsShortTtl: The smallest TTL of a DNS record, in seconds.
const MinDnsShortTtl = 60

// MaxDnsTtl: The largest TTL of a DNS record, in seconds.
const MaxDnsTtl = 604800

// MaxDnsZonesPerJob: The largest number of DNS zones in one job of the agent.
const MaxDnsZonesPerJob = 100

// MaxEnvironmentVariables: The largest number of environment variables of a website.
const MaxEnvironmentVariables = 50

// MaxLogEntries: The largest number of entries in one page of a search in the logs.
const MaxLogEntries = 1000

// MaxLogFilters: The largest number of status codes or of methods in a search in the logs.
const MaxLogFilters = 10

// MaxPackImages: The largest number of images in one pack.
const MaxPackImages = 10

// MaxPackManifestBytes: The largest size of a pack manifest, in bytes.
const MaxPackManifestBytes = 32768

// MaxPacks: The largest number of packs on a panel.
const MaxPacks = 50
